/**
 * @file web_assets.c
 * @brief Exposes the blob linked in by EMBED_FILES.
 *
 * Dependencies: ESP-IDF build system (EMBED_FILES symbols). Threading: read-only.
 */
#include "web_assets.h"

/* Symbols generated by the linker from generated/webapp.bundle.bin
 * (non-alphanumeric characters of the file name become underscores). */
extern const uint8_t webapp_bundle_start[] asm("_binary_webapp_bundle_bin_start");
extern const uint8_t webapp_bundle_end[] asm("_binary_webapp_bundle_bin_end");

/** @copydoc web_assets_get */
const uint8_t *web_assets_get(size_t *len) {
    *len = (size_t)(webapp_bundle_end - webapp_bundle_start);
    return webapp_bundle_start;
}
